{
     "title": "CSCI-251: Concepts of Parallel and Distributed Systems",
     "learningObjectives": [
       "Define the core architectural models of parallel and distributed systems, including multi-core, clusters, grids, client-server, and peer-to-peer topol",
       "Explain how network protocols and security mechanisms protect data integrity and confidentiality in distributed environments",
       "Apply multi-threaded and network programming concepts to design and analyze concurrent system components"
     ],
     "beats": [
       {
         "title": "Foundations of Parallel and Distributed Architecture",
         "claim": "Parallel and distributed systems organize multiple computers to solve complex problems by sharing resources and coordinating tasks across nodes.",
         "example": "A web server cluster distributes incoming HTTP requests across multiple physical machines to handle high traffic loads.",
         "visualDirection": "Display a diagram showing a single server versus a cluster of three servers connected by a network, highlighting load distribution.",
         "sourceIds": ["rit-csci-251"]
       },
       {
         "title": "Multi-Core Computer Organization",
         "claim": "Multi-core computers contain multiple processing units on a single chip that execute threads concurrently to improve computational throughput.",
         "example": "A modern desktop processor with eight cores can execute eight separate program threads simultaneously, reducing execution time for parallelizable workloads.",
         "visualDirection": "Show a close-up illustration of a CPU die with eight distinct cores, each labeled with a thread ID, connected via an internal interconnect.",
         "sourceIds": ["rit-csci-251"]
       },
       {
         "title": "Parallel Computer Clusters and Computing Grids",
         "claim": "Clusters consist of tightly coupled machines working together, while computing grids aggregate geographically dispersed resources to perform large-scale distributed computations.",
         "example": "A scientific research cluster runs molecular dynamics simulations in parallel, whereas a computing grid coordinates thousands of university servers to analyze climate data.",
         "visualDirection": "Draw two side-by-side network maps: one showing a local cluster with direct links, and another showing a grid with regional nodes connected via the internet.",
         "sourceIds": ["rit-csci-251"]
       },
       {
         "title": "Client-Server and Peer-to-Peer Systems",
         "claim": "Client-server systems centralize resources on dedicated servers accessed by requesting clients, while peer-to-peer systems allow equal participants to share data and services.",
         "example": "A bank's online portal uses a client-server model where users connect to central authentication servers, whereas a file-sharing network uses peer-to-peer nodes to exchange documents directly.",
         "visualDirection": "Illustrate a star topology for client-server with a central server node, and a mesh topology for peer-to-peer with interconnected user nodes.",
         "sourceIds": ["rit-csci-251"]
       },
       {
         "title": "Computer Networks and Network Protocols",
         "claim": "Computer networks rely on standardized protocols to ensure reliable data transmission, error detection, and resource allocation across distributed nodes.",
         "example": "The TCP/IP protocol suite manages packet routing, congestion control, and end-to-end delivery, ensuring that data reaches the correct destination despite network failures.",
         "visualDirection": "Show a packet traversing a network with labeled protocol layers (application, transport, network, link) and a status indicator for successful delivery.",
         "sourceIds": ["rit-csci-251"]
       },
       {
         "title": "Network Security and Data Protection",
         "claim": "Network security mechanisms protect distributed systems by encrypting data in transit, verifying identities, and preventing unauthorized access to network resources.",
         "example": "TLS encryption secures web traffic by encrypting payloads and using digital certificates to authenticate the server, preventing man-in-the-middle attacks.",
         "visualDirection": "Display a flowchart showing plaintext data entering a TLS handshake, being encrypted with a symmetric key, and exiting as ciphertext with an integrity tag.",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {
         "title": "Cryptographic Standards and Key Management",
         "claim": "Cryptographic standards define approved algorithms and parameters that ensure confidentiality, integrity, and authenticity when keys and modes are used correctly.",
         "example": "AES-256 encryption with a properly rotated key protects sensitive database records, while a nonce ensures each encryption operation produces a unique ciphertext.",
         "visualDirection": "Show a key management lifecycle diagram with stages: generation, distribution, storage, use, rotation, and destruction, each marked with a checkmark.",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {
         "title": "Multi-Threaded Programming Fundamentals",
         "claim": "Multi-threaded programming allows a single process to execute multiple threads concurrently, sharing memory and resources while requiring synchronization to prevent race conditions",
         "example": "A web application uses separate threads for handling database queries, user authentication, and response generation, coordinated by mutex locks to protect shared variables.",
         "visualDirection": "Illustrate a process with three threads, each with a stack and shared heap, highlighting a mutex lock protecting a critical section.",
         "sourceIds": ["rit-csci-251"]
       },
       {
         "title": "Network Programming and Distributed Communication",
         "claim": "Network programming enables distributed systems to exchange messages using sockets, message queues, or RPC frameworks, requiring careful handling of latency and partial failures.",
         "example": "A distributed caching system uses UDP multicast to broadcast cache invalidation messages, while a RPC framework serializes requests and deserializes responses across network boundaries.",
         "visualDirection": "Show a sequence diagram of an RPC call: client sends request, server processes, server sends response, client receives result, with timeout indicators.",
         "sourceIds": ["rit-csci-251"]
       },
       {
         "title": "Secure Software Development and Verification",
         "claim": "Secure software development practices group activities into preparation, protection, production, and response phases, ensuring security requirements are tracked and verified.",
         "example": "A development team uses a secure software development framework to verify that cryptographic libraries are properly integrated, track security requirements, and remediate vulnerabilities before release.",
         "visualDirection": "Display a four-box flowchart labeled Prepare, Protect, Produce, Respond, with arrows showing continuous feedback loops and a verification badge.",
         "sourceIds": ["nist-ssdf"]
       }
     ]
   }
